-- Notification preferences, quiet hours and deferred emails (FR-NOTIF-002, 004), ADR 012.

-- ============ Part 1: tables (generated by prisma migrate diff) ============
-- AlterTable
ALTER TABLE "notifications" ADD COLUMN     "email_after" TIMESTAMPTZ,
ADD COLUMN     "in_app" BOOLEAN NOT NULL DEFAULT true;

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "quiet_hours_end" SMALLINT,
ADD COLUMN     "quiet_hours_start" SMALLINT,
ADD COLUMN     "timezone" VARCHAR(64);

-- CreateTable
CREATE TABLE "notification_preferences" (
    "org_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "type" VARCHAR(40) NOT NULL,
    "in_app" BOOLEAN NOT NULL DEFAULT true,
    "email" BOOLEAN NOT NULL DEFAULT true,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "notification_preferences_pkey" PRIMARY KEY ("user_id","type")
);

-- CreateIndex
CREATE INDEX "notification_preferences_org_id_idx" ON "notification_preferences"("org_id");

-- CreateIndex
CREATE INDEX "notifications_org_id_email_after_idx" ON "notifications"("org_id", "email_after");

-- AddForeignKey
ALTER TABLE "notification_preferences" ADD CONSTRAINT "notification_preferences_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "notification_preferences" ADD CONSTRAINT "notification_preferences_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- ============ Part 2: rules, security (hand-written) ============

-- Quiet hours are minutes after local midnight, both set or both null, and never equal.
ALTER TABLE users
  ADD CONSTRAINT users_quiet_hours_check CHECK (
    (quiet_hours_start IS NULL AND quiet_hours_end IS NULL)
    OR (quiet_hours_start BETWEEN 0 AND 1439 AND quiet_hours_end BETWEEN 0 AND 1439 AND quiet_hours_start <> quiet_hours_end)
  );

ALTER TABLE notification_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE notification_preferences FORCE ROW LEVEL SECURITY;
CREATE POLICY notification_preferences_org_policy ON notification_preferences FOR ALL
  USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON notification_preferences TO hrvo_app;

-- A preference row must belong to the same organisation as its user.
CREATE FUNCTION fn_notification_pref_same_org() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.user_id AND u.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'notification preference belongs to another organisation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER notification_preferences_same_org BEFORE INSERT OR UPDATE ON notification_preferences
  FOR EACH ROW EXECUTE FUNCTION fn_notification_pref_same_org();
